{

}

Method.Source:
/// <summary>
/// PaffH 13.11.21
/// </summary>
/// <param name = "args">Args</param>
/// <returns>NDXMessageForm</returns>
[SuppressBPWarning('BPParameterNotUsed','args')]
static NDXMessageForm construct(Args args)
{
    return new NDXMessageForm();
}

/// <summary>
/// PaffH 13.11.21
/// </summary>
/// <param name = "args">Args</param>
static void show(Args args)
{

    FormRun formRun;
    args.name(formStr(NDXShowMessage));
    args.formViewOption(FormViewOption::Details);
    formRun = classFactory.formRunClass(args);
    formRun.run();
    FormRun.wait();
}
